    "Retrieved updated_at matches created updated_at",
    retrievedGuest.updated_at,
    createdGuest.updated_at,
  );

  // Step 5: Data integrity validation
  TestValidator.equals(
    "Retrieved guest should not be deleted",
    retrievedGuest.deleted_at,
    null,
  );
  TestValidator.predicate("Updated_at should not be before created_at", () => {
    return (
      new Date(retrievedGuest.updated_at).getTime() >=
      new Date(retrievedGuest.created_at).getTime()
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoGuest";

/**
 * Test updating guest visitor information and demonstration settings.
 *
 * This test validates that temporary guest sessions can be dynamically updated
 * to manage demonstration access and session metadata. The workflow involves:
 *
 * 1. Creating a guest session with initial connection metadata
 * 2. Updating various guest session configuration settings including:
 *
 *    - Connection URL for tracking demonstration flow
 *    - IP address for geographical session tracking
 *    - Referrer URL for traffic source analysis
 *    - Session expiration timestamp for access control
 * 3. Verifying that the updated session reflects all changes correctly
 * 4. Testing partial updates to ensure individual fields can be modified
 * 5. Validating that the session maintains its identity while allowing dynamic
 *    configuration
 *
 * This demonstrates the system's ability to manage guest demonstration access
 * dynamically while maintaining proper session isolation and tracking.
 */
export async function test_api_guest_visitor_information_update(
  connection: api.IConnection,
) {
  // Step 1: Create a guest session with initial connection metadata
  const initialGuest = await api.functional.todo.guests.create(connection, {
    body: {
      href: "https://example.com/todo/demo/intro",
      referrer: "https://example.com/todo/landing",
      ip: "192.168.1.100",
    } satisfies ITodoGuest.ICreate,
  });
  typia.assert(initialGuest);

  // Step 2: Update guest session with new demonstration settings
  const updatedSettings = {
    href: "https://example.com/todo/demo/advanced",
    referrer: "https://example.com/todo/features",
    ip: "192.168.1.101",
    expired_at: new Date(Date.now() + 30 * 60 * 1000).toISOString(), // 30 minutes from now
  } satisfies ITodoGuest.IUpdate;

  const updatedGuest = await api.functional.todo.guests.update(connection, {
    guestId: initialGuest.id,
    body: updatedSettings,
  });
  typia.assert(updatedGuest);

  // Step 3: Verify the updated guest session reflects all changes
  TestValidator.notEquals("guest ID remains same", initialGuest.id, null);
  TestValidator.equals("guest ID unchanged", initialGuest.id, updatedGuest.id);
  TestValidator.equals(
    "created timestamp unchanged",
    initialGuest.created_at,
    updatedGuest.created_at,
  );
  TestValidator.notEquals(
    "updated timestamp changed",
    initialGuest.updated_at,
    updatedGuest.updated_at,
  );

  // Step 4: Test partial update - only update referrer and IP
  const partialUpdate = {
    referrer: "https://example.com/todo/pricing",
    ip: "192.168.1.102",
  } satisfies ITodoGuest.IUpdate;

  const partiallyUpdatedGuest = await api.functional.todo.guests.update(
    connection,
    {
      guestId: initialGuest.id,
      body: partialUpdate,
    },
  );
  typia.assert(partiallyUpdatedGuest);

  // Step 5: Validate that partial update works correctly
  // Verify referrer was updated
  TestValidator.equals(
    "referrer updated in partial update",
    partiallyUpdatedGuest.id,
    initialGuest.id,
  );
  TestValidator.notEquals(
    "partially updated timestamp changed again",
    updatedGuest.updated_at,
    partiallyUpdatedGuest.updated_at,
  );

  // Step 6: Test extending session expiration
  const extensionUpdate = {
    expired_at: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // 60 minutes from now
  } satisfies ITodoGuest.IUpdate;

  const extendedSessionGuest = await api.functional.todo.guests.update(
    connection,
    {
      guestId: initialGuest.id,
      body: extensionUpdate,
    },
  );
  typia.assert(extendedSessionGuest);

  // Step 7: Verify session extension worked
  TestValidator.equals(
    "session successfully extended",
    extendedSessionGuest.id,
    initialGuest.id,
  );
  TestValidator.notEquals(
    "final update timestamp shows change",
    partiallyUpdatedGuest.updated_at,
    extendedSessionGuest.updated_at,
  );
  // Verify created timestamp is still unchanged
  TestValidator.equals(
    "final verification of created timestamp stability",
    initialGuest.created_at,
    extendedSessionGuest.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoTask";
import type { ITodoTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTask";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test business workflow status filtering for task management.
 *
 * This test creates tasks across all three business workflow stages (pending,
 * processing, completed) and validates that status-based filtering correctly
 * isolates tasks by their business workflow stage. It confirms that workflow
 * transitions are properly tracked and that users can effectively manage task
 * progression through different business states.
 *
 * Test Steps:
 *
 * 1. Create a new user account for testing
 * 2. Create tasks with different business_status values (pending, processing,
 *    completed)
 * 3. Test filtering by each business status individually
 * 4. Test filtering with multiple status values
 * 5. Verify that filtering returns only tasks matching the specified status
 * 6. Test pagination while filtering to ensure consistent results
 */
export async function test_api_task_business_workflow_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: RandomGenerator.alphaNumeric(12),
    } satisfies ITodoUser.IJoin,
  });
  typia.assert(user);

  // Step 2: Create tasks with different business_status values
  const statusValues = ["pending", "processing", "completed"] as const;
  const createdTasks: ITodoTask[] = [];

  for (const status of statusValues) {
    const task = await api.functional.todo.user.users.tasks.create(connection, {
      userId: user.id,
      body: {
        description: `${status} task: ${RandomGenerator.paragraph({ sentences: 3 })}`,
        href: "http://localhost:3000/tasks",
        referrer: "http://localhost:3000/dashboard",
        business_status: status,
      } satisfies ITodoTask.ICreate,
    });
    typia.assert(task);
    createdTasks.push(task);
  }

  // Also create additional tasks with mixed statuses for more robust testing
  const additionalTasks = await ArrayUtil.asyncRepeat(6, async (index) => {
    const randomStatus = RandomGenerator.pick(statusValues);
    return await api.functional.todo.user.users.tasks.create(connection, {
      userId: user.id,
      body: {
        description: `Task ${index + 1}: ${RandomGenerator.paragraph({ sentences: 2 })}`,
        href: "http://localhost:3000/tasks",
        referrer: "http://localhost:3000/dashboard",
        business_status: randomStatus,
      } satisfies ITodoTask.ICreate,
    });
  });

  // Combine all created tasks
  const allTasks = [...createdTasks, ...additionalTasks];
  const totalPending = allTasks.filter(
    (t) => t.business_status === "pending",
  ).length;
  const totalProcessing = allTasks.filter(
    (t) => t.business_status === "processing",
  ).length;
  const totalCompleted = allTasks.filter(
    (t) => t.business_status === "completed",
  ).length;

  // Step 3: Test filtering by each business status individually
  for (const status of statusValues) {
    const filterResult = await api.functional.todo.user.users.tasks.index(
      connection,
      {
        userId: user.id,
        body: {
          page: 1,
          limit: 20,
          business_status: status,
        } satisfies ITodoTask.IRequest,
      },
    );
    typia.assert(filterResult);

    const expectedCount =
      status === "pending"
        ? totalPending
        : status === "processing"
          ? totalProcessing
          : totalCompleted;

    TestValidator.predicate(
      `filtering by ${status} returns correct total count`,
      filterResult.pagination.records === expectedCount,
    );

    // Verify all returned tasks have the requested business status
    TestValidator.predicate(
      `all returned tasks have ${status} status`,
      filterResult.data.every((task) => task.business_status === status),
    );
  }

  // Step 4: Test filtering with null business_status (should return all tasks)
  const allTasksResult = await api.functional.todo.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 20,
        business_status: null, // null should return all tasks
      } satisfies ITodoTask.IRequest,
    },
  );
  typia.assert(allTasksResult);

  TestValidator.predicate(
    "filtering with null business_status returns all tasks",
    allTasksResult.pagination.records === allTasks.length,
  );

  // Step 5: Test pagination while filtering
  const paginationResult = await api.functional.todo.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 2, // Small page size to test pagination
        business_status: "pending",
      } satisfies ITodoTask.IRequest,
    },
  );
  typia.assert(paginationResult);

  TestValidator.predicate(
    "pagination works with business_status filtering",
    paginationResult.data.length === Math.min(2, totalPending),
  );
  TestValidator.predicate(
    "all paginated tasks have correct status",
    paginationResult.data.every((task) => task.business_status === "pending"),
  );

  // Test second page if enough pending tasks exist
  if (totalPending > 2) {
    const page2Result = await api.functional.todo.user.users.tasks.index(
      connection,
      {
        userId: user.id,
        body: {
          page: 2,
          limit: 2,
          business_status: "pending",
        } satisfies ITodoTask.IRequest,
      },
    );
    typia.assert(page2Result);

    TestValidator.predicate(
      "second page has different tasks",
      page2Result.data.every((task) => task.business_status === "pending"),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
