  const whitespaceTask = await api.functional.todo.user.tasks.create(
    connection,
    {
      body: {
        description: whitespaceDescription,
        href: "https://example.com/tasks",
        referrer: "https://example.com/dashboard",
      } satisfies ITodoTask.ICreate,
    },
