import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUserSession";
import { IPageITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoUserUsersUserIdSessions(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
  body: ITodoUserSession.IRequest;
}): Promise<IPageITodoUserSession.ISummary> {
  // Authorization check - users can only access their own sessions
  if (props.user.id !== props.userId) {
    throw new HttpException(
      "Unauthorized: You can only access your own session data",
      403,
    );
  }

  const { page, limit, sort_by, sort_order } = props.body;
  const skip = (page - 1) * limit;

  // Build where clause from filters - ALWAYS include user id filter
  const whereClause = {
    todo_user_id: props.userId, // CRITICAL: Only get sessions for this specific user
    ...(props.body.ip !== undefined && { ip: props.body.ip }),
    ...(props.body.referrer !== undefined && { referrer: props.body.referrer }),
    ...(props.body.created_after !== undefined && {
      created_at: { gte: props.body.created_after },
    }),
    ...(props.body.created_before !== undefined && {
      created_at: { lte: props.body.created_before },
    }),
    ...(props.body.expired !== undefined && {
      expired_at: props.body.expired ? { not: null } : null,
    }),
  };

  // Determine Sort
  const orderBy = {
    created_at: sort_order ?? "desc",
  } as const;

  // Handle custom sort fields
  if (sort_by === "ip") {
    Object.assign(orderBy, { ip: sort_order ?? "desc" });
  } else if (sort_by === "expired_at") {
    Object.assign(orderBy, { expired_at: sort_order ?? "desc" });
  }

  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_user_sessions.findMany({
      where: whereClause,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_user_sessions.count({ where: whereClause }),
  ]);

  const data: ITodoUserSession.ISummary[] = sessions.map((session) => ({
    id: session.id,
    ip: session.ip,
    href: session.href,
    referrer: session.referrer,
    created_at: toISOStringSafe(session.created_at),
    expired_at: session.expired_at
      ? toISOStringSafe(session.expired_at)
      : toISOStringSafe(new Date()),
  }));

  return {
    data,
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: Number(total),
      pages: Number(Math.ceil(total / limit)),
    },
  } satisfies IPageITodoUserSession.ISummary;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function postAuthGuestJoin(props: {
  guest: GuestPayload;
}): Promise<ITodoGuest.IAuthorized> {
  // Create guest record
  const guest = await MyGlobal.prisma.todo_guests.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
    },
  });

  // Create session record - use empty strings since we don't have IP/referrer context
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
  const session = await MyGlobal.prisma.todo_guest_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_guest_id: guest.id,
      ip: "",
      href: "",
      referrer: "",
      created_at: new Date(),
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens
  const now = new Date();
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return formatted response - convert Prisma Date objects to ISO strings
  return {
    id: guest.id,
    created_at: toISOStringSafe(guest.created_at),
    updated_at: toISOStringSafe(guest.updated_at),
    deleted_at:
      guest.deleted_at !== null ? toISOStringSafe(guest.deleted_at) : null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoUser.ILogin;
}): Promise<ITodoUser.IAuthorized> {
  // Find user by email
  const user = await MyGlobal.prisma.todo_users.findUnique({
    where: { email: props.body.email },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Check account security status
  const isLocked =
    user.locked_until && new Date(user.locked_until) > new Date();

  if (isLocked) {
    throw new HttpException("Account is locked. Please try again later", 423);
  }
  if (user.failed_login_attempts >= 5) {
    throw new HttpException(
      "Too many failed login attempts. Account locked",
      423,
    );
  }

  // Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );

  if (!isValid) {
    // Update failed attempts atomically with lockout on 5th attempt
    const now = toISOStringSafe(new Date());
    const newAttemptCount = user.failed_login_attempts + 1;
    const shouldLockout = newAttemptCount >= 5;

    await MyGlobal.prisma.todo_users.update({
      where: { id: user.id },
      data: {
        failed_login_attempts: newAttemptCount,
        locked_until: shouldLockout ? now : user.locked_until,
        updated_at: now,
      },
    });
    throw new HttpException("Invalid credentials", 401);
  }

  // Reset failed attempts since login was successful
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
  const currentTime = toISOStringSafe(new Date());

  // Create new session
  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_user_id: user.id,
      ip: props.body.ip ?? "", // FIXED: Removed invalid props.ip reference
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: currentTime,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Reset failed login attempts and clear lockout
  await MyGlobal.prisma.todo_users.update({
    where: { id: user.id },
    data: {
      failed_login_attempts: 0,
      locked_until: null,
      updated_at: currentTime,
    },
  });

  // Count active tasks for the user
  const tasksCount = await MyGlobal.prisma.todo_tasks.count({
    where: { todo_user_id: user.id },
  });

  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: currentTime,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: currentTime,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return authorized user data with converted timestamps
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: currentTime,
    mfa_enabled: user.mfa_enabled,
    failed_login_attempts: 0,
    locked_until: null,
    tasks_count: tasksCount,
    token,
  } satisfies ITodoUser.IAuthorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postAuthUserRefresh(props: {
  user: UserPayload;
  body: ITodoUser.IRefresh;
}): Promise<ITodoUser.IAuthorized> {
  try {
    // Step 1: Verify and decode refresh token
    const decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "user";
      tokenType?: string;
    };

    // Verify this is a refresh token
    if (decoded.tokenType !== "refresh") {
      throw new HttpException("Invalid token type for refresh", 401);
    }

    // Verify payload matches the user making request
    if (
      decoded.id !== props.user.id ||
      decoded.session_id !== props.user.session_id
    ) {
      throw new HttpException("Token mismatch with current user", 401);
    }

    // Step 2: Validate user exists and is active
    const user = await MyGlobal.prisma.todo_users.findFirst({
      where: {
        id: decoded.id,
        deleted_at: null,
      },
    });

    if (!user) {
      throw new HttpException("User not found or inactive", 404);
    }

    // Step 3: Generate new tokens with SAME session_id
    const accessExpires = toISOStringSafe(
      new Date(Date.now() + 60 * 60 * 1000),
    );
    const refreshExpires = toISOStringSafe(
      new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
    );

    const accessToken = jwt.sign(
      {
        type: props.user.type,
        id: props.user.id,
        session_id: props.user.session_id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: props.user.type,
        id: props.user.id,
        session_id: props.user.session_id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    // Step 4: Get user's task count
    const tasksCount = await MyGlobal.prisma.todo_tasks.count({
      where: {
        todo_user_id: user.id,
      },
    });

    // Step 5: Return new authorization
    return {
      id: user.id,
      email: user.email,
      created_at: toISOStringSafe(user.created_at),
      updated_at: toISOStringSafe(user.updated_at),
      mfa_enabled: user.mfa_enabled,
      failed_login_attempts: user.failed_login_attempts satisfies number,
      locked_until: user.locked_until
        ? toISOStringSafe(user.locked_until)
        : undefined,
      tasks_count: tasksCount satisfies number,
      token: {
        access: accessToken,
        refresh: refreshToken,
        expired_at: accessExpires,
        refreshable_until: refreshExpires,
      },
    } satisfies ITodoUser.IAuthorized;
  } catch (error) {
    if (
      error instanceof jwt.JsonWebTokenError ||
      error instanceof jwt.TokenExpiredError
    ) {
      throw new HttpException("Invalid or expired refresh token", 401);
    }
    if (error instanceof jwt.NotBeforeError) {
      throw new HttpException("Token not yet valid", 401);
    }
    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTask";
import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoUserTasks(props: {
  user: UserPayload;
  body: ITodoTask.ICreate;
}): Promise<ITodoTask> {
  const { user, body } = props;

  // Default business_status to "pending" if not provided
  const businessStatus = body.business_status ?? "pending";

  // Create task with required fields
  const created = await MyGlobal.prisma.todo_tasks.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_user_id: user.id,
      description: body.description,
      completed: false,
      business_status: businessStatus,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
    include: {
      user: true,
    },
  });

  // Create session for connection tracking
  await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_user_id: user.id,
      ip: body.ip ?? "",
      href: body.href,
      referrer: body.referrer,
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Get current task count for user
  const tasksCount = await MyGlobal.prisma.todo_tasks.count({
    where: { todo_user_id: user.id },
  });

  // Return formatted task object with proper type handling
  return {
    id: created.id as string & tags.Format<"uuid">,
    description: created.description,
    completed: created.completed,
    business_status: created.business_status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at: created.completed_at
      ? toISOStringSafe(created.completed_at)
      : null,
