  const [users, totalCount] = await Promise.all([
    MyGlobal.prisma.todo_users.findMany({
      where,
      include: {
        _count: {
          select: { todo_tasks: true },
        },
      },
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_users.count({ where }),
  ]);

